/**
 * The shared contract between the engine, the CFO agent and the dashboard.
 *
 * Every type here has a matching JSON Schema in this folder
 * (`*.schema.json`). Change both together and bump SCHEMA_VERSION when a
 * change is not backwards compatible.
 *
 * Money is stored as integer nanos of USD (1 USD = 1_000_000_000), the unit
 * the Agent Orchestrator usage endpoint reports. Config files use plain USD.
 */

export const SCHEMA_VERSION = 1;

export type TaskSize = 'small' | 'medium' | 'large';

/** Outcome of one attempt. `stopped` means the watcher killed it at its ceiling. */
export type AttemptResult = 'passed' | 'failed' | 'stopped' | 'error';

/** How the cost on a row was obtained. */
export type CostSource =
  /** tokens x list price from tally.yaml (the default, comparable across harnesses) */
  | 'list-price'
  /** the Agent Orchestrator's own estimate, used only when no list price is configured */
  | 'ao-estimate'
  /** a dry-run or demo attempt that spent nothing */
  | 'simulated';

/** How an escalated attempt received the earlier attempt's work. */
export type Handoff = 'none' | 'restart' | 'entire-handoff';

export interface TokenUsage {
  /** Input tokens billed at the full input price. Includes cache writes. */
  uncachedInput: number;
  /** Input tokens read from cache. */
  cachedInput: number;
  output: number;
  /** uncachedInput + cachedInput + output */
  total: number;
}

/** One row per attempt. A task that escalates has two rows. */
export interface LedgerRow {
  schemaVersion: 1;
  /** `${runId}:${taskId}:${attempt}` */
  attemptId: string;
  runId: string;
  taskId: string;
  taskTitle: string;
  /** 1 for the first attempt, 2 for the escalation. */
  attempt: number;
  size: TaskSize;
  /** Name of the tier in tally.yaml that ran this attempt. */
  tier: string;
  model: string;
  harness: string;
  /** Agent Orchestrator session id; null for simulated attempts. */
  sessionId: string | null;
  branch: string | null;
  tokens: TokenUsage;
  estimatedCostNanos: number;
  costSource: CostSource;
  /** Spend ceiling that applied to this attempt. */
  ceilingNanos: number;
  result: AttemptResult;
  /** Short explanation of the result, e.g. "2 tests failing" or "ceiling crossed". */
  resultReason: string | null;
  /** attemptId of the attempt this one took over from, if it is an escalation. */
  escalatedFrom: string | null;
  handoff: Handoff;
  prUrl: string | null;
  traceUrl: string | null;
  checkpointId: string | null;
  checkpointUrl: string | null;
  /** The CFO agent's one-sentence reason for choosing this tier. */
  decision: string;
  startedAt: string;
  endedAt: string | null;
}

export type Ledger = LedgerRow[];

export type RunMode = 'tally' | 'baseline';
export type RunStatus = 'running' | 'finished' | 'interrupted';
export type TaskStatus = 'pending' | 'running' | 'passed' | 'failed' | 'skipped';
export type BudgetSource = 'config' | 'cfoai';

export type IntegrationName = 'neatlogs' | 'entire' | 'cfoai' | 'github' | 'slack';
/** `off` = switched off in config, `missing` = on but not usable, `error` = failed during the run. */
export type IntegrationStatus = 'ok' | 'off' | 'missing' | 'error';

export interface IntegrationState {
  status: IntegrationStatus;
  /** What Tally does instead, or what went wrong. */
  detail: string | null;
}

export interface TaskState {
  taskId: string;
  title: string;
  issueNumber: number | null;
  issueUrl: string | null;
  /** null until the sizer has run. */
  size: TaskSize | null;
  status: TaskStatus;
  /** Why a task is failed or skipped, e.g. "not started: no budget". */
  statusReason: string | null;
  attempts: number;
  /** Tier of the latest attempt. */
  tier: string | null;
  model: string | null;
  spentNanos: number;
  escalated: boolean;
  prUrl: string | null;
}

export interface RunState {
  schemaVersion: 1;
  runId: string;
  mode: RunMode;
  /** True when workers were simulated and nothing was spent. */
  dryRun: boolean;
  status: RunStatus;
  /** The repository the run worked on, as written in tally.yaml. */
  repo: string;
  /** Commit every task branched from. */
  baseCommit: string | null;
  startedAt: string;
  updatedAt: string;
  endedAt: string | null;
  budget: {
    source: BudgetSource;
    limitNanos: number;
    /** Always the sum of estimatedCostNanos over this run's ledger rows. */
    spentNanos: number;
  };
  tasks: TaskState[];
  integrations: Record<IntegrationName, IntegrationState>;
}

export interface TierPrice {
  inputUsdPerMTok: number;
  cachedInputUsdPerMTok: number;
  outputUsdPerMTok: number;
}

export interface Tier {
  /** Free-form label, e.g. cheap / middle / top. Referenced by ledger rows. */
  name: string;
  /** Any harness the Agent Orchestrator supports. */
  harness: string;
  model: string;
  /** Published list price. Cost is always tokens x this. */
  price: TierPrice;
  /** Share of the size ceiling this tier may spend, in (0, 1]. */
  ceilingFraction: number;
}

export interface TallyConfig {
  version: 1;
  repo: {
    /** Local checkout, relative to tally.yaml. */
    path: string;
    /** owner/name on GitHub, when issues or PRs are used. */
    slug?: string;
    baseBranch: string;
    /** Agent Orchestrator project id, when it differs from the default for the checkout. */
    aoProject?: string;
  };
  test: {
    /** Run in the task's checkout; exit code 0 means the task passed. */
    command: string;
    /** Run once per fresh checkout before the test command. */
    setupCommand?: string;
    timeoutSec?: number;
  };
  backlog: {
    source: 'github-issues' | 'file';
    issueLabel?: string;
    /** YAML backlog file, relative to tally.yaml. */
    file?: string;
  };
  /** Ordered from cheapest to strongest. Escalation moves one step right. */
  tiers: Tier[];
  ceilings: {
    /** What the strongest tier may spend on a task of each size, in USD. */
    bySizeUsd: Record<TaskSize, number>;
  };
  budget: {
    source: BudgetSource;
    /** The budget, or the fallback when the cfo.ai scenario cannot be read. */
    usd: number;
    cfoai?: { scenario: string };
  };
  concurrency?: number;
  integrations: Record<'neatlogs' | 'entire' | 'cfoai' | 'slack', boolean>;
}
import type { TallyConfig, TaskSize, Tier, TierPrice, TokenUsage } from './types.js';

export const NANOS_PER_USD = 1_000_000_000;

export function usdToNanos(usd: number): number {
  return Math.round(usd * NANOS_PER_USD);
}

export function nanosToUsd(nanos: number): number {
  return nanos / NANOS_PER_USD;
}

/** Tokens x list price, in nanos. A price per million tokens is 1000 nanos per token per USD. */
export function costNanos(tokens: TokenUsage, price: TierPrice): number {
  return Math.round(
    tokens.uncachedInput * price.inputUsdPerMTok * 1000 +
      tokens.cachedInput * price.cachedInputUsdPerMTok * 1000 +
      tokens.output * price.outputUsdPerMTok * 1000,
  );
}

/** The spend ceiling for one attempt: the size ceiling scaled by the tier's fraction. */
export function ceilingNanos(config: TallyConfig, size: TaskSize, tier: Tier): number {
  return usdToNanos(config.ceilings.bySizeUsd[size] * tier.ceilingFraction);
}

export function attemptId(runId: string, taskId: string, attempt: number): string {
  return `${runId}:${taskId}:${attempt}`;
}
export * from './types.js';
export * from './money.js';
export * from './validate.js';
{
  "name": "tally",
  "version": "0.1.0",
  "description": "A CFO for a fleet of coding agents: budgets, routing, ceilings and a ledger per task.",
  "type": "module",
  "license": "MIT",
  "engines": {
    "node": ">=20"
  },
  "bin": {
    "tally": "bin/tally.js"
  },
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "vitest run",
    "test:watch": "vitest",
    "tally": "tsx cli/main.ts"
  },
  "dependencies": {
    "ajv": "^8.20.0",
    "ajv-formats": "^3.0.1",
    "yaml": "^2.9.1"
  },
  "devDependencies": {
    "@types/node": "^26.6.5",
    "tsx": "^4.23.15",
    "typescript": "^7.0.2",
    "vitest": "^5.0.3"
  }
}
{
  "compilerOptions": {
    "target": "ES2022",
    "module": "NodeNext",
    "moduleResolution": "NodeNext",
    "strict": true,
    "noUncheckedIndexedAccess": true,
    "resolveJsonModule": true,
    "types": ["node"],
    "esModuleInterop": true,
    "skipLibCheck": true,
    "declaration": true,
    "sourceMap": true,
    "rootDir": ".",
    "outDir": "dist"
  },
  "include": ["schema", "engine", "cli", "adapters", "agent"],
  "exclude": ["dist", "node_modules"]
}
import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    include: ['{schema,engine,cli,adapters,agent}/**/*.test.ts'],
  },
});
# Tally

A CFO for a fleet of coding agents. Give it a backlog and a budget. It sizes
each task, sends it to the cheapest model likely to finish it, stops any task
that overruns its spend ceiling, hands failed work to a stronger model, and
ends with a ledger tying every dollar to a merged PR.

Status: early scaffold. The shared data contract and the CLI entry point
exist; the commands are stubs.

## Setup

Needs Node 20 or later.

```bash
npm install
npm test          # unit tests
npm run build     # compile to dist/
node bin/tally.js --help
```

During development, `npm run tally -- <command>` runs the CLI from source.

## Commands

| Command | What it will do |
|---|---|
| `tally run` | Run the backlog against the budget in `tally.yaml`. Flags: `--dry-run`, `--budget <usd>`, `--only <task>`, `--baseline`, `--config <path>`. |
| `tally demo` | Run the full loop with simulated workers on a sample backlog. No accounts or keys. |
| `tally init` | Detect the test command, ask for a budget and issue label, and write `tally.yaml`. |
| `tally doctor` | One line per integration: connected, missing or broken, with the fix. |

## Layout

| Folder | Holds |
|---|---|
| `schema/` | The contract every part reads: TypeScript types, JSON Schema, validators, and a sample finished run in `schema/fixtures/finished-run/`. |
| `engine/` | The run loop, run state and ledger. |
| `adapters/` | One thin module per outside tool (Agent Orchestrator, Entire, neatlogs, cfo.ai, GitHub). |
| `agent/` | The CFO agent: sizing, routing, ceilings, escalation. |
| `cli/` | The `tally` command. |
| `dashboard/` | Static page that reads the ledger and run state. |
| `demo/` | Sample backlog and scripted outcomes for `tally demo`. |

## Configuration

Tally assumes nothing about the repository it works on. The repository, test
command, model tiers, list prices, ceilings and budget all come from
`tally.yaml`; see `schema/fixtures/finished-run/tally.yaml` for a complete
example and `schema/tally-config.schema.json` for the rules.

Money in the ledger and run state is stored as integer nanos of USD
(1 USD = 1,000,000,000). Cost is always tokens multiplied by the list price in
`tally.yaml`.

## Secrets

Keys live in `~/.tally/.env`, outside every repository, and are loaded from
there. Never put them in this repo; `.env` files are git-ignored.
